package com.sfood.eai.external.logger;

import org.junit.jupiter.api.Test;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.test.context.SpringBootTest;

import java.sql.SQLException;

@SpringBootTest
public class SlackAppenderTest {

    private static final Logger log = LoggerFactory.getLogger(SlackAppenderTest.class);

    @Test
    public void sendSqlErrorTest() {
        // 컬럼 사이즈 오류 메시지
        String errorMessage = "ORA-12899: value too large for column \"SFOOD_OMS_DEV\".\"TBL_GODO_ADD_GOODS\".\"LIST_IMAGE_DATA\" (actual: 115, maximum: 20)";

        // SQL 예외 생성
        SQLException sqlException = new SQLException(errorMessage);

        // 로그 출력 - 이 로그는 SlackAppender에 의해 Slack으로 전송됨
        log.error("could not execute statement [{}] [update TBL_GODO_ADD_GOODS set ADD_GOODS_NO=?,ADD_GOODS_PRICE=?,API_ORDER_GOODS_NO=?,ASSIGN_GOODS_CNT=?,BRAND_BANK_SALE_PRICE=?,CANCEL_DT=?,CATE_ALL_CD=?,COMMISSION=?,COST_PRICE=?,COUPON_GOODS_DC_PRICE=?,COUPON_GOODS_MILEAGE=?,COUPON_MILEAGE_FL=?,CREATE_ID=?,DELIVERY_COMPLETE_DT=?,DELIVERY_DT=?,DELIVERY_METHOD_FL=?,DELIVERY_SCHEDULE_FL=?,DIVISION_COUPON_ORDER_DC_PRICE=?,DIVISION_COUPON_ORDER_MILEAGE=?,DIVISION_GOODS_DELIVERY_USE_DEPOSIT=?,DIVISION_GOODS_DELIVERY_USE_MILEAGE=?,DIVISION_USE_DEPOSIT=?,DIVISION_USE_MILEAGE=?,EASYPAY_SCM_RECEIPT_FL=?,ENURI=?,EVENT_SNO=?,FINISH_DT=?,FIXED_PRICE=?,GOODS_CD=?,GOODS_CNT=?,GOODS_DC_PRICE=?,GOODS_DELIVERY_COLLECT_FL=?,GOODS_DELIVERY_COLLECT_PRICE=?,GOODS_DISCOUNT_INFO=?,GOODS_MILEAGE=?,GOODS_MILEAGE_ADD_INFO=?,GOODS_MODEL_NO=?,GOODS_NM=?,GOODS_NM_STANDARD=?,GOODS_PRICE=?,GOODS_TYPE=?,GOODS_VOLUME=?,HSCODE=?,INFLOW=?,INVOICE_COMPANY=?,INVOICE_COMPANY_SNO=?,INVOICE_DT=?,INVOICE_NO=?,LINK_MAIN_THEME=?,LIST_IMAGE_DATA=?,MALL_SNO=?,MEMBER_DC_PRICE=?,MEMBER_MILEAGE=?,MEMBER_OVERLAP_DC_PRICE=?,MILEAGE_GIVE_DT=?,MINUS_DEPOSIT_FL=?,MINUS_MILEAGE_FL=?,MINUS_RESTORE_DEPOSIT_FL=?,MINUS_RESTORE_MILEAGE_FL=?,MINUS_RESTORE_STOCK_FL=?,MINUS_STOCK_FL=?,MYAPP_DC_PRICE=?,OPTION_COST_PRICE=?,OPTION_INFO=?,OPTION_PRICE=?,OPTION_SNO=?,OPTION_TEXT_INFO=?,OPTION_TEXT_PRICE=?,ORDER_CD=?,ORDER_DELIVERY_SNO=?,ORDER_GROUP_CD=?,ORDER_STATUS=?,PARENT_GOODS_NO=?,PARENT_MUST_FL=?,PAYMENT_DT=?,PLUS_MILEAGE_FL=?,PLUS_RESTORE_MILEAGE_FL=?,PURCHASE_NO=?,SCM_ADJUST_AFTER_NO=?,SCM_NO=?,SEND_SMS_FL=?,STATISTICS_GOODS_FL=?,STATISTICS_ORDER_FL=?,TIME_SALE_FL=?,TIME_SALE_PRICE=?,UPDATE_DATE=?,UPDATE_ID=?,VISIT_ADDRESS=? where ORDER_NO=? and SNO=?]",
                errorMessage, sqlException);
    }
}